#!/usr/bin/env bash
set -Eeuo pipefail
export_and_import_database() { PHASE=database; record_local_metadata; local sql="$DEPLOY_RUNTIME/local.sql" gz="$DEPLOY_RUNTIME/local.sql.gz" checksum remote_checksum; export_local_database "$sql" || die 6 'LocalWP database export failed'; gzip -c "$sql" > "$gz"; gzip -t "$gz" || die 6 'local database archive is invalid'; checksum=$(sha256 "$gz"); if [ "$DRY_RUN" -eq 1 ]; then dry "would upload $gz to $(remote_backup_dir), verify checksum, reset only $PRODUCTION_EXPECTED_DB_NAME, import, and execute serialized-safe search-replace dry-runs"; wp_remote search-replace "$LOCAL_HOME" "$PRODUCTION_URL" --all-tables-with-prefix --precise --skip-columns=guid --dry-run; return; fi; ssh_args; scp "${SSH_CONNECTION_ARGS[@]}" "$gz" "$PRODUCTION_SSH_USER@$PRODUCTION_SSH_HOST:$(remote_backup_dir)/database-local.sql.gz"; remote_checksum=$(remote_exec "{ if command -v shasum >/dev/null 2>&1; then shasum -a 256 $(shell_quote "$(remote_backup_dir)/database-local.sql.gz"); elif command -v sha256sum >/dev/null 2>&1; then sha256sum $(shell_quote "$(remote_backup_dir)/database-local.sql.gz"); else exit 127; fi; } | awk '{print \\$1}'"); [ "$checksum" = "$remote_checksum" ] || die 6 'database upload checksum mismatch'; if [ "$LOCAL_PREFIX" != "$REMOTE_PREFIX" ]; then remote_exec "cd $(shell_quote "$PRODUCTION_ROOT") && $REMOTE_WP_COMMAND config set table_prefix $(shell_quote "$LOCAL_PREFIX") --type=variable" || die 6 'TABLE_PREFIX_RECONCILIATION_REQUIRED'; fi; remote_exec "cd $(shell_quote "$PRODUCTION_ROOT") && test \"\$($REMOTE_WP_COMMAND db query 'SELECT DATABASE()' --skip-column-names)\" = $(shell_quote "$PRODUCTION_EXPECTED_DB_NAME") && $REMOTE_WP_COMMAND db reset --yes && gzip -dc $(shell_quote "$(remote_backup_dir)/database-local.sql.gz") | $REMOTE_WP_COMMAND db import -" || die 6 'database import failed'; wp_remote option update home "$PRODUCTION_URL"; wp_remote option update siteurl "$PRODUCTION_URL"; wp_remote core is-installed || die 6 'imported database is not a WordPress installation'; for url in "$LOCAL_HOME" "$LOCAL_WP_URL"; do [ -n "$url" ] || continue; wp_remote search-replace "$url" "$PRODUCTION_URL" --all-tables-with-prefix --precise --skip-columns=guid --dry-run; wp_remote search-replace "$url" "$PRODUCTION_URL" --all-tables-with-prefix --precise --skip-columns=guid; done; remote_exec "cd $(shell_quote "$PRODUCTION_ROOT") && $REMOTE_WP_COMMAND db search '.local' --all-tables-with-prefix --format=count | grep -q '^0$'" || die 7 'remaining LocalWP URLs detected'; }
restore_production_settings() { [ "$DRY_RUN" -eq 1 ] && return; wp_remote option update home "$PRODUCTION_URL"; wp_remote option update siteurl "$PRODUCTION_URL"; wp_remote option update blog_public 1; wp_remote theme activate rentacar-venezia-v2; wp_remote plugin activate rentacar-core polylang || die 6 'required plugin activation failed'; for p in sitepress-multilingual-cms wpml-string-translation wpml-translation-management acfml; do wp_remote plugin deactivate "$p" >/dev/null 2>&1 || true; done; }
